"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["57161"],{22209(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>o,contentTitle:()=>i,toc:()=>l,assets:()=>h});var a=JSON.parse('{"id":"qiangguo/learnfromjapanese","title":"","description":"Without the Japanese, even if China\'s May Fourth Movement had occurred, it probably would not have taken its present form. No matter how much entanglement there is between the Chinese and the Japanese, this point of history cannot be denied. And this is just one example of the reversal in Sino-Japanese cultural transmission that began in the late Qing.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/learnfromjapanese.md","sourceDirName":"qiangguo","slug":"/qiangguo/learnfromjapanese","permalink":"/en/qiangguo/learnfromjapanese","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"learnfromjapanese","title":"","hide_table_of_contents":true,"sidebar_label":"From the perspective of cultural dissemination and inheritance, Chinese people must learn from the Japanese."},"sidebar":"qiangguoSidebar","previous":{"title":"Western modern economics must be fully deconstructed \u2014 economics is essentially just political science plus psychology (2004-9-14)","permalink":"/en/qiangguo/moderneconomics"},"next":{"title":"\u53F0\u6E7E\u4E0E\u671D\u9C9C\uFF0C\u6700\u7EC8\u4E00\u4E2A\u90FD\u4E0D\u4F1A\u4E5F\u4E0D\u80FD\u5C11\u3002","permalink":"/en/qiangguo/taiwanandkorean"}}'),s=n(74848),r=n(28453);let o={id:"learnfromjapanese",title:"",hide_table_of_contents:!0,sidebar_label:"From the perspective of cultural dissemination and inheritance, Chinese people must learn from the Japanese."},i="From the Standpoint of Cultural Transmission and Inheritance, the Chinese Must Learn from the Japanese",h={},l=[];function d(e){let t={h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"from-the-standpoint-of-cultural-transmission-and-inheritance-the-chinese-must-learn-from-the-japanese",children:"From the Standpoint of Cultural Transmission and Inheritance, the Chinese Must Learn from the Japanese"})}),"\n",(0,s.jsx)(t.p,{children:"Without the Japanese, even if China's May Fourth Movement had occurred, it probably would not have taken its present form. No matter how much entanglement there is between the Chinese and the Japanese, this point of history cannot be denied. And this is just one example of the reversal in Sino-Japanese cultural transmission that began in the late Qing."}),"\n",(0,s.jsx)(t.p,{children:'For roughly a thousand years, the Japanese were nothing but elementary students before the Chinese. But everything changed in a legendary shipwreck. When the great Mongol armada became shark food, the Japanese suddenly felt they had earned the capital for fantasy: "The entire Eurasian continent lay beneath the Mongol iron heel, yet the Japanese survived thanks to a maritime disaster -- could we truly be the chosen ones?" Watching the celestial empire they once worshipped being trampled by barbarians time and again, the Japanese went from dumplings to darlings.'}),"\n",(0,s.jsx)(t.p,{children:'In the second half of the 19th century, when the Chinese discovered in Japan the Yogacara Buddhist texts that had been transmitted during the Tang Dynasty but lost in China, the Chinese were finally shocked to find that after the barbarization by the Yuan and Qing, those Chinese cultural treasures thought to have been lost forever had been so well preserved in the hands of the "dwarf pirates." Here it must be mentioned that after the fall of the Ming Dynasty, both Korea and Japan only nominally acknowledged the Qing while internally still regarding the Ming as the legitimate continuation of Chinese civilization. One must understand that for over a thousand years, Korea, Japan, and the countries of Southeast Asia all regarded China as the celestial empire and their suzerain state. This is the truth of history.'}),"\n",(0,s.jsx)(t.p,{children:"Later, everything changed. When the Japanese discovered that the Western terminology they had coined became the new vernacular vocabulary of the celestial empire, they again felt the same sensation as when the Mongol armada fed the sharks. History has consistently proven that to conquer the Japanese, one can only do so through culture -- just as they prostrated themselves before the cultural radiance of the great Tang. If even culture cannot command the Japanese's respect, on what basis would you demand their respect?"}),"\n",(0,s.jsx)(t.p,{children:"Culture is always paramount. America's most powerful weapon is not nuclear weapons but McDonald's and Hollywood. When the Chinese once again make the Japanese come across the seas as the Tang Dynasty envoys once did, China will be truly powerful again. Now, regardless of whether everyone is comfortable hearing this, it still must be said: from the standpoint of cultural transmission and inheritance, the Chinese must learn from the Japanese."})]})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>i});var a=n(96540);let s={},r=a.createContext(s);function o(e){let t=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),a.createElement(r.Provider,{value:t},e.children)}}}]);